from pathlib import Path
from html.parser import HTMLParser
import zipfile, xml.etree.ElementTree as E
class Parser(HTMLParser):
    def __init__(self): super().__init__(); self.parts=[]; self.skip=0; self.links=[]; self.href=None; self.label=[]
    def handle_starttag(self,tag,attrs):
        if tag in ('script','style'): self.skip+=1
        if tag in ('p','div','li','br','h1','h2','h3','tr'): self.parts.append('\\n')
        if tag=='a': self.href=dict(attrs).get('href'); self.label=[]
    def handle_endtag(self,tag):
        if tag in ('script','style'): self.skip-=1
        if tag=='a' and self.href is not None:
            self.links.append((''.join(self.label).strip(),self.href)); self.href=None
    def handle_data(self,data):
        if not self.skip:
            self.parts.append(data)
            if self.href is not None: self.label.append(data)
for f in list(Path('pages').glob('*.htm'))+[Path('jinji_R6.html')]:
    p=Parser(); p.feed(f.read_text(encoding='utf-8-sig'))
    lines=[s.strip() for s in ''.join(p.parts).splitlines() if s.strip()]
    Path('evidence',f.stem+'.txt').write_text('\\n'.join(lines)+'\\n\\nLINKS\\n'+'\\n'.join(f'{a}\\t{b}' for a,b in p.links))
ns={'s':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
with zipfile.ZipFile('hanzai_r07_4-11-1.xlsx') as z:
    strings=[''.join(t.itertext()) for t in E.fromstring(z.read('xl/sharedStrings.xml')).findall('s:si',ns)]
    out=[]
    out.append(z.read('xl/workbook.xml').decode())
    for name in z.namelist():
        if name.startswith('xl/worksheets/sheet') and name.endswith('.xml'):
            out.append('\\n'+name)
            for row in E.fromstring(z.read(name)).findall('s:sheetData/s:row',ns):
                values=[]
                for c in row.findall('s:c',ns):
                    v=c.find('s:v',ns)
                    if v is not None:
                        val=strings[int(v.text)] if c.get('t')=='s' else v.text
                        values.append(c.get('r')+'='+val)
                if values: out.append(' | '.join(values))
    Path('evidence/hanzai_cells.txt').write_text('\\n'.join(out))
